extra_css:
/* the hero sub-line — the Sunrise skeleton has none; --slate-light is 4.83:1
   on the gradient's worst stop (a11y-perf §6) */
.post-hero__sub { font-size: 1.05rem; max-width: 640px; margin: 0 auto 1.5rem; line-height: 1.7; color: var(--slate-light); }
/* the Source evidence tag — this series labels references Source · Study ·
   Synthesis; REFERENCES_CSS carries the other three. Amber family to match
   the covers; #7c4a03 measures 5.9:1 on --bg. */
.ref-tag--source { background: rgba(245,158,11,0.16); color: #7c4a03; }
